void ScriptSession::neutralSpellInfo(SpellInfo& s){
    auto& data=definitions();auto field=[&](const char* key){return data.number(s.ability,"AbilityData",std::string(key)+std::to_string(s.level));};
    if(s.kind==SpellKind::DrunkenHaze){auto silence=s;silence.kind=SpellKind::Silence;arrowStatusInfo(silence);s.disableMask=silence.disableMask;s.missChance=silence.missChance;s.moveReduction=silence.moveReduction;s.moveBonus=silence.moveBonus;s.attackReduction=silence.attackReduction;s.attackBonus=silence.attackBonus;if(s.speed<=0)throw std::runtime_error("Drunken Haze requires source missile speed");return;}
    if(s.kind==SpellKind::BreathFire || s.kind==SpellKind::ForkedLightning){s.distance=field("DataC");s.endRadius=field("DataD");if(s.distance<=0 || s.distance>100000 || s.endRadius<0 || s.endRadius>100000)throw std::runtime_error("Neutral cone geometry outside supported range");if(s.kind==SpellKind::BreathFire){s.maxDamage=s.secondary;s.extraDamage=field("DataE");if(s.speed<=0 || s.extraDamage<0 || s.extraDamage>1000000 || s.duration>86400 || s.heroDuration>86400)throw std::runtime_error("Breath of Fire burn or missile outside supported range");}else {s.targets=count(s.secondary,1024);s.loss=0;if(!s.targets || s.duration<=0 || s.duration>86400)throw std::runtime_error("Forked Lightning requires source targets and graphic duration");}return;}
    if(s.kind==SpellKind::RainFire){s.pulses=count(s.amount,1024);s.shards=count(field("DataC"),128);s.period=field("Cast");s.channelTime=s.pulses*s.period;s.channelled=true;s.amount=field("DataB");s.maxDamage=field("DataF");s.buildingFactor=field("DataD");s.extraDamage=field("DataE");if(s.allowed.empty() || s.allowed.contains("_"))s.allowed={"ground","structure","enemy","friend","self","neutral","tree","debris"};auto buffs=data.field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));if(buffs.size()>=9 && buffs[4]==',')s.guardBuff=ObjectData::code(buffs.substr(5,4));if(!s.buff || !s.pulses || s.period<=0 || s.period>300 || s.duration<0 || s.duration>86400 || s.heroDuration<0 || s.heroDuration>86400 || s.extraDamage<0 || s.extraDamage>1000000 || s.buildingFactor<0 || s.buildingFactor>10)throw std::runtime_error("Rain of Fire source schedule outside supported range");return;}
    if(s.kind==SpellKind::Doom){s.summonCount=count(s.secondary,64);s.summonDuration=s.loss;s.creepLevel=count(field("DataD"),100);auto type=data.field(s.ability,"AbilityData","UnitID"+std::to_string(s.level)),buffs=data.field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));if(type.size()!=4 || !data.contains(ObjectData::code(type)) || !s.buff || !s.summonCount || s.summonDuration<=0 || s.summonDuration>86400 || s.amount<0 || s.amount>1000000)throw std::runtime_error("Doom requires source damage, summon and lifetime");s.summonType=ObjectData::code(type);if(buffs.size()>=9 && buffs[4]==',')s.guardBuff=ObjectData::code(buffs.substr(5,4));}
}
bool ScriptSession::neutralSpellImpact(const SpellMissile& missile){
    auto& s=missile.spell;if(s.kind!=SpellKind::DrunkenHaze && s.kind!=SpellKind::Doom && s.kind!=SpellKind::ForkedLightning)return false;if(!alive(missile.source,NativeKind::Unit) || !alive(missile.target,NativeKind::Unit))return true;auto source=units_.at(missile.source),target=units_.at(missile.target);if(!spellTarget(*source,*target,s,false,missile.owner))return true;
    if(s.kind==SpellKind::DrunkenHaze){silenceEffect(missile.source,s,{target->x,target->y},missile.owner);return true;}
    if(s.kind==SpellKind::Doom){applyBuff(missile.target,missile.source,s,BuffKind::Doom);auto found=target->buffs.find(s.buff);if(found==target->buffs.end() || found->second.kind!=BuffKind::Doom)return true;auto& b=found->second;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=missile.owner;b.applied=++spellTicket_;b.damage=s.amount;b.persistent=true;b.dispellable=false;if(target->cast)cancelCast(*target);return true;}
    float dx=number(target->x)-number(source->x),dy=number(target->y)-number(source->y),length=std::hypot(dx,dy);if(length>.001f){dx/=length;dy/=length;}else{float angle=number(source->facing)*3.14159265359f/180;dx=std::cos(angle);dy=std::sin(angle);}std::vector<std::pair<float,std::uint32_t>> candidates;for(auto& [id,u]:units_)if(id!=missile.target && spellTarget(*source,*u,s,false,missile.owner)){float x=number(u->x)-number(source->x),y=number(u->y)-number(source->y),along=x*dx+y*dy,radius=s.area+(s.endRadius-s.area)*std::clamp(along/s.distance,0.f,1.f);if(along<0 || along>s.distance+u->collision || std::abs(x*dy-y*dx)>radius+u->collision)continue;candidates.emplace_back(std::hypot(number(u->x)-number(target->x),number(u->y)-number(target->y)),id);}std::sort(candidates.begin(),candidates.end());std::vector<std::uint32_t> victims{missile.target};for(auto [distance,id]:candidates){if(victims.size()>=s.targets)break;victims.push_back(id);}auto revision=source->deathRevision,ownership=source->ownerRevision;
    for(auto id:victims){if(!alive(missile.source,NativeKind::Unit) || source->removing || number(source->life)<=0 || source->deathRevision!=revision || source->ownerRevision!=ownership || source->owner!=missile.owner)break;if(!alive(id,NativeKind::Unit) || !spellTarget(*source,*units_.at(id),s,false,missile.owner))continue;auto beam=missile;beam.target=id;beam.visited.clear();spellLightning(beam);spellVisual(s,"Specialart",id,{units_.at(id)->x,units_.at(id)->y});damageUnit(missile.source,id,s.amount,0,14);}return true;
}
void ScriptSession::breathFireHit(std::uint32_t source,std::uint32_t target,const SpellInfo& s,unsigned owner,float amount){
    if(!alive(source,NativeKind::Unit) || !alive(target,NativeKind::Unit))return;auto victim=units_.at(target);auto revision=victim->deathRevision;bool burnEligible=definitions().field(s.ability,"AbilityData","code",ObjectData::name(s.ability))=="ACbf";for(auto& [id,b]:victim->buffs)if(b.kind==BuffKind::DrunkenHaze && b.remaining>0){burnEligible=true;break;}damageUnit(source,target,amount,0,14);if(!burnEligible || s.extraDamage<=0 || !alive(target,NativeKind::Unit) || victim->removing || number(victim->life)<=0 || victim->deathRevision!=revision)return;applyBuff(target,source,s,BuffKind::BreathBurn);auto found=victim->buffs.find(s.buff);if(found!=victim->buffs.end() && found->second.kind==BuffKind::BreathBurn){found->second.damage=s.extraDamage;found->second.sourceOwner=owner;}
}
float ScriptSession::neutralBurnTick(UnitBuff& b,double elapsed){
    if(b.kind==BuffKind::AcidBomb)return acidBombTick(b,elapsed);
    if(b.kind==BuffKind::SoulBurn)return firelordBuffTick(b,elapsed);
    if(b.kind!=BuffKind::BreathBurn && b.kind!=BuffKind::RainBurn && b.kind!=BuffKind::Doom)return 0;b.period+=elapsed;float damage=0;while(b.period>=1){b.period-=1;damage+=b.damage;}return damage;
}
void ScriptSession::doomDeath(const UnitState& victim){
    if(victim.hero || victim.building || victim.illusion || victim.exploded || !alive(victim.handle,NativeKind::Unit))return;std::optional<UnitBuff> mark;for(auto& [id,b]:victim.buffs)if(b.kind==BuffKind::Doom && b.originAbility && b.sourceLevel && b.sourceOwner<16 && (!mark || b.applied>mark->applied))mark=b;if(!mark)return;auto& s=spellInfo(mark->originAbility,mark->sourceLevel);auto current=units_.at(victim.handle);auto active=[&]{return alive(victim.handle,NativeKind::Unit) && !current->removing && number(current->life)<=0 && current->deathRevision==victim.deathRevision;};WorldPoint point{victim.x,victim.y};if(!active() || (current->corpse && current->corpse->consumed) || !summonPoint(point,s.summonType))return;if(current->corpse){current->corpse->consumed=true;current->corpse->flags=0;}auto art=s;art.ability=s.guardBuff?s.guardBuff:s.buff;auto visuals=spellVisual(art,"Effectart",0,point);for(auto id:visuals)if(effects_.contains(id))effects_.at(id)->fallbackExpires=simulationTime_+16;
    for(unsigned i=0;i<s.summonCount;++i){if(!active())return;auto place=summonPoint(point,s.summonType);if(!place)break;auto handle=createUnit(mark->sourceOwner,s.summonType,place->x,place->y,victim.facing);if(!alive(handle.bits,NativeKind::Unit))continue;auto unit=units_.at(handle.bits);if(!active() || unit->removing || number(unit->life)<=0 || unit->owner!=mark->sourceOwner || unit->type!=s.summonType){if(!unit->removing)removeUnit(handle.bits);if(!active())return;continue;}unit->summoner=mark->source;unit->summonAbility=s.ability;unit->timedLife=TimedLife{s.guardBuff,s.summonDuration,s.summonDuration,false};if(s.guardBuff)unit->abilities[s.guardBuff]=1;summonedEvent(mark->source,handle.bits,mark->sourceOwner);}
}
void ScriptSession::parasiteDeath(const UnitState& victim){
    if(victim.hero || victim.building || victim.illusion || victim.exploded || !alive(victim.handle,NativeKind::Unit))return;std::optional<UnitBuff> mark;for(auto& [id,b]:victim.buffs)if(b.kind==BuffKind::Parasite && b.originAbility && b.sourceLevel && b.sourceOwner<16 && (!mark || b.applied>mark->applied))mark=b;if(!mark)return;auto& s=spellInfo(mark->originAbility,mark->sourceLevel);auto current=units_.at(victim.handle);auto active=[&]{return alive(victim.handle,NativeKind::Unit) && !current->removing && number(current->life)<=0 && current->deathRevision==victim.deathRevision;};WorldPoint point{victim.x,victim.y};if(!active() || (current->corpse && current->corpse->consumed) || !summonPoint(point,s.summonType))return;if(current->corpse){current->corpse->consumed=true;current->corpse->flags=0;}
    for(unsigned i=0;i<s.summonCount;++i){if(!active())return;auto place=summonPoint(point,s.summonType);if(!place)break;auto handle=createUnit(mark->sourceOwner,s.summonType,place->x,place->y,victim.facing);if(!alive(handle.bits,NativeKind::Unit))continue;auto unit=units_.at(handle.bits);if(!active() || unit->removing || number(unit->life)<=0 || unit->owner!=mark->sourceOwner || unit->type!=s.summonType){if(!unit->removing)removeUnit(handle.bits);if(!active())return;continue;}unit->summoner=mark->source;unit->summonAbility=s.ability;if(s.summonDuration>0)unit->timedLife=TimedLife{s.guardBuff,s.summonDuration,s.summonDuration,false};if(s.guardBuff)unit->abilities[s.guardBuff]=1;spellVisual(s,"TargetArt",handle.bits,*place);summonedEvent(mark->source,handle.bits,mark->sourceOwner);}
}
void ScriptSession::spawnOnDeath(const UnitState& victim){
    if(victim.illusion || !alive(victim.handle,NativeKind::Unit))return;auto current=units_.at(victim.handle);auto active=[&]{return alive(victim.handle,NativeKind::Unit) && !current->removing && number(current->life)<=0 && current->deathRevision==victim.deathRevision;};for(auto [ability,level]:passiveAbilities(victim)){auto& p=passiveInfo(ability,level);if(p.kind!=PassiveKind::SpawnOnDeath)continue;for(unsigned i=0;i<unsigned(p.amount) && active();++i){auto at=summonPoint({victim.x,victim.y},p.corpseType);if(!at)break;createUnit(victim.owner,p.corpseType,at->x,at->y,victim.facing);}}
}
